from collections import Counter

class Solution:
    def isPossible(self, nums: list[int]) -> bool:
        remain = Counter(nums)
        tails = Counter()
        for num in nums:
            if remain[num] == 0:
                continue
            if tails[num] > 0:
                tails[num] -= 1
                tails[num + 1] += 1
            elif remain[num + 1] > 0 and remain[num + 2] > 0:
                remain[num + 1] -= 1
                remain[num + 2] -= 1
                tails[num + 3] += 1
            else:
                return False
            remain[num] -= 1
        return True

